"""Regenerate docs/prompt-catalog.md from the built-in prompt packs: python scripts/gen_prompt_catalog.py"""

from __future__ import annotations

from collections import defaultdict
from pathlib import Path

from model_forensic.ai.prompts import PromptLibrary


def render() -> str:
    lib = PromptLibrary.load()
    by_cat: dict[str, list] = defaultdict(list)
    for p in lib.all():
        by_cat[p.category].append(p)
    out = [
        "# Prompt template catalog",
        "",
        "_Generated by `scripts/gen_prompt_catalog.py` from `backend/src/model_forensic/ai/prompt_packs/`. Do not edit by hand._",
        "",
        f"{sum(len(v) for v in by_cat.values())} templates. **Baseline** = compares against a baseline run; "
        "**multi-run** = uses all runs in scope (`--other` on the CLI, *Ask AI about these runs* in Progression). "
        "Variables marked * are required.",
        "",
    ]
    for cat in sorted(by_cat):
        out += [f"## {cat}", "", "| Id | Title | Needs | Variables | Extra evidence |", "|---|---|---|---|---|"]
        for p in sorted(by_cat[cat], key=lambda x: x.id):
            needs = ", ".join(x for x in ["baseline" if p.needs_baseline else "",
                                          "multi-run" if "{{run_ids}}" in p.template and "{{#run_ids}}" not in p.template else ""] if x)
            variables = ", ".join(f"`{v}`{'*' if v in p.requires else ''}" for v in sorted(p.variables - {"run_id", "baseline_run_id", "run_ids"}))
            ev = []
            if p.include.logs != "none":
                ev.append(f"logs: {p.include.logs}")
            if p.include.series:
                ev.append("curves: " + ", ".join(f"`{s}`" for s in p.include.series))
            if p.include.config_keys:
                ev.append(f"{len(p.include.config_keys)} config patterns")
            if p.include.slices:
                ev.append("slices")
            out.append(f"| `{p.id}` | {p.title} — {p.description} | {needs or '—'} | {variables or '—'} | {'; '.join(ev) or '—'} |")
        out.append("")
    return "\n".join(out)


if __name__ == "__main__":
    path = Path(__file__).resolve().parents[1] / "docs" / "prompt-catalog.md"
    path.write_text(render())
    print(f"wrote {path}")
